import {routePieces,lineDistance,interpolate,GEOMETRY_METHOD} from './geometry.mjs';
import {currentTriangle,nextUtcMonth,MOTION_METHOD} from './motion.mjs';
import {profileSuitability,clone} from '../fuel/vesselProfile.mjs';
import {mainEnginePerformance} from '../fuel/enginePerformance.mjs';
import {fuelMassKg} from '../fuel/fuelConsumption.mjs';
import {carbonEmissions} from '../fuel/carbonEmissions.mjs';
import {fuelCost} from '../fuel/economicComparison.mjs';
import {validIso} from '../fuel/voyageSegments.mjs';
import {sha256} from '../fuel/calculationProvenance.mjs';
import {ENGINE_MODEL,FACTOR_VERSION,SOURCES} from '../fuel/fuelFactors.mjs';
import {voyageEconomics} from './economics.mjs';
import {routeSourceNoise} from './acoustics.mjs';

export const VOYAGE_METHOD=Object.freeze({id:'wa-source-aware-voyage',version:'1.0.0',geometry:GEOMETRY_METHOD,motion:MOTION_METHOD,power:ENGINE_MODEL,emissionsFactorVersion:FACTOR_VERSION});
export class VoyageDataService{
  constructor({environmentalDataService,trafficDataService=null,ecologicalModels=null,protectionDataService=null}={}){Object.assign(this,{environmentalDataService,trafficDataService,ecologicalModels,protectionDataService});}
  async evaluate({route,profile,departureIso,stwKnots,currentMode='monthly-currents',economics={},arrivalTargetIso=null},{signal=null,onProgress=()=>{}}={}){
    const check=()=>{if(signal?.aborted)throw Error('analysis_cancelled');};
    const issues=profileSuitability(profile);if(issues.length)return {status:'blocked',reason:'vessel_profile_incomplete_or_unsupported',issues,routeId:route?.id};
    if(!validIso(departureIso)||arrivalTargetIso!==null&&(!validIso(arrivalTargetIso)||Date.parse(arrivalTargetIso)<=Date.parse(departureIso)))return {status:'blocked',reason:'departure_or_arrival_required'};
    if(!['monthly-currents','still-water'].includes(currentMode))return {status:'blocked',reason:'explicit_current_mode_required'};
    if(route?.status!=='found'||route.engineVersion!=='hydra-geometric-astar-1.0.0'||!/^[a-f0-9]{64}$/.test(route.topologySha256||'')||route.navigationallyValidated!==false)return {status:'blocked',reason:'checked_geometric_route_required'};
    let pieces,performance;try{pieces=routePieces(route.coordinates);performance=mainEnginePerformance(profile,stwKnots);if(profile.minimumSpeedKnots!=null&&stwKnots<profile.minimumSpeedKnots)throw Error('below_declared_operating_speed');}catch(e){return {status:'blocked',reason:e.message};}
    const snapshot={route:clone(route),profile:clone(profile),departureIso,stwKnots,currentMode,economics:clone(economics),arrivalTargetIso},rows=[],sourceMap=new Map(),environmentSamples=[],fuelById={},scope=profile.auxiliary.mode==='unknown'?'main-engine-only':'main-and-declared-auxiliary',start=Date.parse(departureIso);let stamp=start,mainKg=0,auxKg=profile.auxiliary.mode==='unknown'?null:0,progress=0;
    const capture=r=>{if(r?.source){const key=(r.datasetId||'')+':'+(r.datasetRevision||'')+':'+(r.source.sha256||'')+':'+(r.calendarPeriod||r.time||'');sourceMap.set(key,{datasetId:r.datasetId,revision:r.datasetRevision,source:r.source,time:r.time,calendarPeriod:r.calendarPeriod??null,sourceInterval:r.sourceInterval,units:r.units,uncertainty:r.uncertainty,quality:r.quality});}};
    try{
      for(let index=0;index<pieces.length;index++){
        check();const piece=pieces[index];let remaining=piece.distanceNM,used=0,boundaries=0;
        while(remaining>1e-8){
          check();if(++boundaries>120)throw Error('segment_time_integration_limit');const date=new Date(stamp).toISOString(),midpoint=interpolate(piece.from,piece.to,(used+remaining*.5)/piece.distanceNM);
          const current=currentMode==='still-water'?null:await this.environmentalDataService.getEnvironmentalValue('current_vector',midpoint[1],midpoint[0],date,{temporalMode:'calendar-month',bearingDegrees:piece.bearingDegrees});check();capture(current);
          if(currentMode==='monthly-currents'&&(current?.status!=='available'||!Number.isFinite(current.vector?.u)||!Number.isFinite(current.vector?.v)))return {status:'blocked',reason:'current_coverage_incomplete',sourceStatus:current?.status,sourceReason:current?.reason,at:{longitude:midpoint[0],latitude:midpoint[1],date},routeId:route.id,distanceNM:lineDistance(route.coordinates),knownDistanceNM:progress,totals:null,partialTimeline:rows,sourceRecords:[...sourceMap.values()],navigationCleared:false};
          const motion=currentTriangle(stwKnots,piece.bearingDegrees,current?.vector.u??0,current?.vector.v??0);if(motion.status!=='computed')return {status:'blocked',reason:motion.status,at:{longitude:midpoint[0],latitude:midpoint[1],date},routeId:route.id,totals:null,navigationCleared:false};
          const hoursToBoundary=(nextUtcMonth(stamp)-stamp)/3600000,hours=Math.min(remaining/motion.sogKnots,hoursToBoundary),distance=Math.min(remaining,hours*motion.sogKnots);if(!Number.isFinite(hours)||hours<=0||distance<=0)throw Error('invalid_duration');
          const endStamp=hours===hoursToBoundary?nextUtcMonth(stamp):stamp+hours*3600000,from=interpolate(piece.from,piece.to,used/piece.distanceNM),to=interpolate(piece.from,piece.to,(used+distance)/piece.distanceNM),center=interpolate(from,to,.5),sampleTime=new Date(stamp+hours*1800000).toISOString();
          const mainFuelKg=fuelMassKg(performance.powerKw,performance.sfocGPerKwh,hours);mainKg+=mainFuelKg;fuelById[profile.fuelId]=(fuelById[profile.fuelId]??0)+mainFuelKg;let auxiliaryFuelKg=null;
          if(profile.auxiliary.mode==='defined'){auxiliaryFuelKg=fuelMassKg(profile.auxiliary.nominalPowerKw*profile.auxiliary.load,profile.auxiliary.sfocGPerKwh,hours);auxKg+=auxiliaryFuelKg;fuelById[profile.auxiliary.fuelId]=(fuelById[profile.auxiliary.fuelId]??0)+auxiliaryFuelKg;}else if(profile.auxiliary.mode==='none-confirmed')auxiliaryFuelKg=0;
          const sst=await this.environmentalDataService.getEnvironmentalValue('sst',center[1],center[0],sampleTime,{temporalMode:'interval-mean'});check();capture(sst);
          const traffic=this.trafficDataService?await this.trafficDataService.getTransitValue(center[1],center[0],sampleTime,{temporalMode:'annual-background'}):{status:'not_integrated',value:null};check();capture(traffic);
          const row={index:rows.length,from,to,midpoint:center,distanceNM:distance,offsetNM:progress,startIso:new Date(stamp).toISOString(),endIso:new Date(endStamp).toISOString(),durationHours:hours,...motion,...performance,mainFuelKg,auxiliaryFuelKg,current:current?{status:current.status,u:current.vector.u,v:current.vector.v,units:'m/s',time:current.time,calendarPeriod:current.calendarPeriod,datasetId:current.datasetId,revision:current.datasetRevision,gridCell:current.gridCell,sourceSha256:current.source.sha256,uncertainty:current.uncertainty}:null,sst:{status:sst.status,value:sst.value,units:sst.units||'°C',time:sst.time,gridCell:sst.gridCell,uncertainty:sst.uncertainty,reason:sst.reason},traffic:{status:traffic.status,value:traffic.value,units:traffic.units,time:traffic.time,gridCell:traffic.gridCell,reason:traffic.reason}};
          rows.push(row);environmentSamples.push({longitude:center[0],latitude:center[1],date:sampleTime,distanceNM:distance,stwKnots,sogKnots:motion.sogKnots});stamp=endStamp;used+=distance;remaining-=distance;progress+=distance;
        }
        if(index%12===0){onProgress({fraction:(index+1)/pieces.length,stage:'sampling'});await new Promise(resolve=>setTimeout(resolve,0));}
      }
      const co2ByFuel=carbonEmissions(fuelById),co2Kg=Object.values(co2ByFuel).reduce((n,v)=>n+v,0),fuelKg=Object.values(fuelById).reduce((n,v)=>n+v,0),durationHours=(stamp-start)/3600000,price=fuelCost(fuelById,profile.prices),totals={distanceNM:progress,durationHours,etaIso:new Date(stamp).toISOString(),stwKnots,meanSogKnots:progress/durationHours,mainFuelKg:mainKg,auxiliaryFuelKg:auxKg,fuelKg,fuelTonnes:fuelKg/1000,wholeVesselFuelKg:auxKg===null?null:fuelKg,co2Kg,co2Tonnes:co2Kg/1000,co2KgPerNM:co2Kg/progress,arrivalTargetMet:arrivalTargetIso?stamp<=Date.parse(arrivalTargetIso):null};
      const summarize=(key)=>{let d=0,sum=0,min=Infinity,max=-Infinity;const missing={};for(const r of rows){const s=r[key];if(s.status==='available'&&Number.isFinite(s.value)){d+=r.distanceNM;sum+=s.value*r.distanceNM;min=Math.min(min,s.value);max=Math.max(max,s.value);}else missing[s.reason||s.status]=(missing[s.reason||s.status]||0)+r.distanceNM;}return {status:Math.abs(d-progress)<1e-7?'complete':d?'partial':'unavailable',coveredDistanceNM:d,totalDistanceNM:progress,coverageFraction:d/progress,coveredDistanceWeightedMean:d?sum/d:null,mean:Math.abs(d-progress)<1e-7?sum/progress:null,min:d?min:null,max:d?max:null,missingDistanceByReason:missing};};
      const sources=[...sourceMap.values()],comparisonContext={profile:snapshot.profile,departureIso,currentMode,economics:snapshot.economics,arrivalTargetIso,model:VOYAGE_METHOD,environmentRevisions:[...new Set(sources.map(s=>s.datasetId+':'+s.revision))].sort()},provenance={calculatedAt:new Date().toISOString(),method:VOYAGE_METHOD,sourceRecords:sources,sources:SOURCES,inputSha256:await sha256(snapshot),comparisonKey:await sha256(comparisonContext),inputs:snapshot,assumptions:[currentMode==='monthly-currents'?'historical near-surface monthly vectors; piecewise-constant midpoint sampling; split at reached UTC calendar boundaries':'explicit zero-current scenario; no inference about actual sea conditions','STW drives power; cross-current-compensated SOG drives time','no wind, waves, squat, weather or machinery aging model','cartographic land/ice shelf check only; depth/draft/regulations unverified','direct combustion CO2; not lifecycle CO2e','only declared economic components; no company profit']};check();
      return {status:'computed',id:route.id,name:route.name,route,profileId:profile.id,profileVersion:profile.version,departureIso,scope,totals,fuelById,co2ByFuel,fuelCost:price,economics:voyageEconomics({fuelCost:price,durationHours,co2Kg,scope},economics),noise:routeSourceNoise(profile,rows),environment:{sst:summarize('sst'),traffic:summarize('traffic'),currentMode},segments:rows,environmentSamples,provenance,navigationCleared:false};
    }catch(e){if(e.message==='analysis_cancelled')throw e;return {status:'blocked',reason:e.message,routeId:route.id,totals:null,navigationCleared:false};}
  }
}
